-- ============================================================================
-- payer-rules-oh-appendixdd-humana.sql
--
-- Ohio Medicaid's Appendix DD coverage, fanned out to the FIFTH Ohio Medicaid
-- MCO: Humana Healthy Horizons of Ohio.
--
-- payer-rules-fee-schedules-full.sql states the rule it fans on, and it is the
-- right rule: "A state Medicaid schedule is the state's coverage determination
-- and a Medicaid plan must cover what the state covers, so it fans to that
-- state's Medicaid plans only. Commercial plans (Anthem Ohio, Humana Ohio,
-- Aetna, Medical Mutual) are excluded -- Ohio Medicaid has no authority over
-- them and asserting coverage would be invention."
--
-- The reasoning was never wrong. The INPUT was: 'Humana Ohio' was filed as a
-- commercial payer, so the fan-out skipped it. It is not commercial. It is
-- Humana Healthy Horizons of Ohio, a Medicaid product of Humana Health Plan of
-- Ohio, Inc. -- corrected in 0008_phase4_payers.sql. Ohio Medicaid's schedule
-- has exactly the same authority over it as over Molina, Buckeye, CareSource
-- and UnitedHealthcare Community Plan, which all carry these rules already.
--
-- Every row is COPIED from UnitedHealthcare Community Plan Ohio's Appendix DD
-- rules: same document, same verbatim row citation, same status, same rate,
-- same effective date. Nothing is re-derived, so this cannot disagree with the
-- state determination the other four already serve.
--
-- This is the annual-rulebook model working as intended. One document, revised
-- once a year by the state, answering 259 rules per plan -- rather than
-- chasing per-payer PDFs that move or vanish.
-- ============================================================================

BEGIN;

VALUES ('f4d00000-0000-4000-8000-00000000dd08'::uuid, 'a0000000-0000-4000-8000-000000000308'::uuid, 'https://dam.assets.ohio.gov/raw/upload/medicaid.ohio.gov/Providers/FeeScheduleRates/OutpatientHospital/5160-1-60-_App_DD-_Updates_for_01_01_2026-_FINAL.xlsx', 'state_medicaid_manual',
        'Ohio Medicaid — Appendix DD to rule 5160-1-60, Non-Institutional Fee Schedule (rev. 01/01/2026)',
        now(), 'sha256:full-OH|a0000000-0000-4000-8000-000000000308', FALSE, '{}'::jsonb, now())
ON CONFLICT (id) DO UPDATE SET
  url = EXCLUDED.url, document_type = EXCLUDED.document_type, title = EXCLUDED.title,
  content_hash = EXCLUDED.content_hash, retrieved_at = EXCLUDED.retrieved_at,
  extracted_at = EXCLUDED.extracted_at;

UPDATE payer_rule pr
   SET expiration_date = GREATEST(pr.effective_date, DATE '2026-01-01')
 WHERE pr.expiration_date IS NULL
   AND pr.payer_id = 'a0000000-0000-4000-8000-000000000308'::uuid
   AND pr.attribute = 'covered'
   AND pr.created_by <> 'extract:oh-appendixdd-humana-2026-08';

ON CONFLICT (id) DO UPDATE SET
  value = EXCLUDED.value, coverage_status = EXCLUDED.coverage_status,
  product_line = EXCLUDED.product_line, confidence = EXCLUDED.confidence,
  source_quote = EXCLUDED.source_quote, effective_date = EXCLUDED.effective_date,
  expiration_date = NULL, source_doc_id = EXCLUDED.source_doc_id;

COMMIT;
